"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["17762"],{83545(e){e.exports=JSON.parse('{"id":"FIN-297","slug":"supply-curve","term":"Supply Curve","also_known_as":[],"difficulty":"Intermediate","definition":"A supply curve is a graph showing the relationship between the price of a good and the quantity producers are willing to supply at each price, with all other factors held constant.","explanation":["On a typical supply curve, price is shown on the vertical axis and quantity on the horizontal axis. The curve usually slopes upwards from left to right, because higher prices encourage producers to supply more.","For example, a bakery might be willing to supply 100 loaves a day at 2 each, 150 loaves at 2.50 and 200 loaves at 3. Plotting these points gives a rising supply curve.","Movement along the curve happens when the product\'s own price changes. The whole curve shifts when other factors change. If flour becomes more expensive, the bakery\'s costs rise and it will supply fewer loaves at each price, so the curve shifts to the left. If new ovens make baking cheaper, it will supply more at each price, and the curve shifts to the right.","The steepness of the supply curve reflects how responsive producers are to price changes, which is measured by the price elasticity of supply."],"note":"","total":1500,"prev":{"slug":"supply-chain-finance","term":"Supply Chain Finance"},"next":{"slug":"supply-side-economics","term":"Supply-Side Economics"}}')}}]);